package com.dudleylane.quickfix.fix41;

/** FIX 4.1 Email (35=C). Generated by spec/GeneratorJava.rb. */
public class Email extends Message {
    public static final String MSGTYPE = "C";

    public Email() {
        getHeader().setField(35, MSGTYPE);
    }

    private Email(long cPtr) {
        super(cPtr, false);
    }

    /**
     * message as a Email, without copying it: the same engine object, so valid only while message is. A
     * callback's message is the engine's and lasts only for the callback; copy it (new Message(message)) to keep it.
     */
    public static Email view(com.dudleylane.quickfix.Message message) {
        if (!MSGTYPE.equals(message.getHeader().getField(35))) {
            throw new IllegalArgumentException("not a Email (35=" + MSGTYPE + "): 35=" + message.getHeader().getField(35));
        }
        return new Email(getCPtr(message));
    }

    /** A new NoRelatedSym group, as this one holds it. */
    public static com.dudleylane.quickfix.fix41.group.NoRelatedSym newNoRelatedSym() {
        return new com.dudleylane.quickfix.fix41.group.NoRelatedSym();
    }

    /** A new LinesOfText group, as this one holds it. */
    public static com.dudleylane.quickfix.fix41.group.LinesOfText newLinesOfText() {
        return new com.dudleylane.quickfix.fix41.group.LinesOfText();
    }
}
